import java.util.*;import java.util.zip.*;import java.nio.file.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
public class RecruitAbi {
 static Map<String,ClassNode> classes=new HashMap<>();
 static boolean has(String owner,String name,String desc,boolean field){var c=classes.get(owner);if(c==null)return false;if(field?c.fields.stream().anyMatch(f->f.name.equals(name)&&f.desc.equals(desc)):c.methods.stream().anyMatch(m->m.name.equals(name)&&m.desc.equals(desc)))return true;if(c.superName!=null&&has(c.superName,name,desc,field))return true;for(var i:c.interfaces)if(has(i,name,desc,field))return true;return false;}
 public static void main(String[]args)throws Exception{try(var z=new ZipFile(args[0])){for(var e:Collections.list(z.entries()))if(e.getName().endsWith(".class")){var c=new ClassNode();new ClassReader(z.getInputStream(e)).accept(c,ClassReader.SKIP_CODE);classes.put(c.name,c);}}
 Set<String> missing=new TreeSet<>();try(var z=new ZipFile(args[1])){for(var e:Collections.list(z.entries()))if(e.getName().endsWith(".class")){var c=new ClassNode();new ClassReader(z.getInputStream(e)).accept(c,0);for(var m:c.methods)for(var n:m.instructions){String o=null,name=null,d=null;boolean f=false;if(n instanceof MethodInsnNode x){o=x.owner;name=x.name;d=x.desc;}if(n instanceof FieldInsnNode x){o=x.owner;name=x.name;d=x.desc;f=true;}if(o!=null&&o.startsWith("com/talhanation/recruits/")&&!name.startsWith("m_")&&!name.startsWith("f_")&&!has(o,name,d,f))missing.add(o+"."+name+d);}}}missing.forEach(System.out::println);System.out.println("Missing="+missing.size());}
}
